import{_ as e,o as i,c as a,a7 as t}from"./chunks/framework.DUCm5Bu5.js";const p=JSON.parse('{"title":"更新日志","description":"面向公开版本的带日期变更记录。","frontmatter":{"title":"更新日志","description":"面向公开版本的带日期变更记录。","updated":"2026-10-20T00:00:00.000Z"},"headers":[],"relativePath":"project/changelog.md","filePath":"project/changelog.md"}'),o={name:"project/changelog.md"};function c(r,l,n,d,s,u){return i(),a("div",null,[...l[0]||(l[0]=[t('<h2 id="未发布-—-2026-10-20-utc-08-00" tabindex="-1">未发布 — 2026-10-20（UTC+08:00） <a class="header-anchor" href="#未发布-—-2026-10-20-utc-08-00" aria-label="Permalink to &quot;未发布 — 2026-10-20（UTC+08:00）&quot;">​</a></h2><ul><li>KR2026 的商店购买遵循客户端自身商店表中的物品条款：限时物品会到期，永久物品保持永久，条款拒绝的购买会收到失败回复且不扣费。含有耐久计数物品的六个套装在该版本的规则确定之前暂时无法购买。</li><li>KR2026 商店的所有封包现在都按名称从该版本的 opcode 表查找。打开礼物盒的已发送列表不再触发购买，退款请求也不再收到物品卡片的应答。</li><li>KR2026 的新账号现在会进入客户端自带的角色创建画面，与旧版本一致。KR2026 也会在玩家离线期间物品到期后显示原生的到期通知。</li><li>修复旧版本中持有未记录期限物品的账号无法登录的问题，以及 cn-404、cn-406、cn-408 与 cn-706 的首次登录问题。</li><li>KR2026、cn-774 与 tw-454 改由共用的登录适配器登录。使用自定义补丁的运营者请注意：已移除的 <code>dialect.modern.messages</code> 登录选项列在仓库的 <code>CHANGELOG.md</code> 中；补丁中仍有已移除的键时，启动会失败，删除后即可恢复。</li><li>启动检查现在会验证绑定读写的每个封包字段的类型，因此封包表若改变了字段类型，会在服务器启动时报错，而不是在收到第一个封包时出错。</li><li>故障排查页说明了 <code>NU1900</code> 包审计错误，以及无法连接 nuget.org 时如何构建。</li></ul><h2 id="未发布-—-2026-10-18-utc-08-00" tabindex="-1">未发布 — 2026-10-18（UTC+08:00） <a class="header-anchor" href="#未发布-—-2026-10-18-utc-08-00" aria-label="Permalink to &quot;未发布 — 2026-10-18（UTC+08:00）&quot;">​</a></h2><ul><li>扩充四语言指南并补齐可验证步骤：安装与快速开始区分源码构建与尚未发布的构建包；配置记录 profile 组合、环境变量、端口、持久化与客户端数据；部署覆盖 Docker Compose、备份、升级与回退；故障排查按「症状 → 检查 → 原因 → 处理」组织。</li><li>插件指南新增可实际执行的第一个插件流程；SDK 协议参考新增各语言快速上手、能力协商与一致性测试内容。</li><li>重写中英文 README，补充环境要求、Windows 与 Linux 快速开始、Docker Compose、客户端数据边界与文档入口。</li><li>修正与当前代码不符的描述；尚未发布的下载与安装入口继续标注为即将提供。本次仅涉及文档，运行行为没有改变。</li><li>新增四语言「启动器」指南：配套 Fantasy Tale Launcher 的客户端版本、会话与登录票据模型、hook 插件、分发边界，以及面向运营者的服务端 <code>launcher.http</code> API，包括 HTTP 426 版本门禁、JSON 兼容规则与票据安全边界。仅涉及文档。</li></ul><h2 id="未发布-—-2026-10-16-utc-08-00" tabindex="-1">未发布 — 2026-10-16（UTC+08:00） <a class="header-anchor" href="#未发布-—-2026-10-16-utc-08-00" aria-label="Permalink to &quot;未发布 — 2026-10-16（UTC+08:00）&quot;">​</a></h2><ul><li>增加原生事件总线上的声明式 SDK 事件，支持跨语言串行/并行通知、waterfall 拦截与 bail 决策。</li><li>保留事件续调的所有权并完善 Rust 回调清理；修复关闭时可能遗漏已记录激活超时的竞争问题。</li><li>为 Python、TypeScript、Go 和 Rust 增加 SDK 服务提供者、装饰链及有序服务集合，包含 Go/Rust WebAssembly。</li><li>取消和超时后保留已进入工作的所有权，修正发布新定义后的启动选择。</li><li>插件行超时后仍执行 SDK 清理；共享进程继续存活时，允许回收已退役的激活上下文。</li><li>在插件与 SDK 指南中补充注册示例、生命周期规则和仍未实现的原生对等能力。</li></ul><h2 id="未发布-—-2026-10-15-utc-08-00" tabindex="-1">未发布 — 2026-10-15（UTC+08:00） <a class="header-anchor" href="#未发布-—-2026-10-15-utc-08-00" aria-label="Permalink to &quot;未发布 — 2026-10-15（UTC+08:00）&quot;">​</a></h2><ul><li>准备新的公开文档与 Vue 3 四语言文档站。</li><li>增加 Windows x64/ARM64 下载入口与 Linux 安装脚本/Docker 选项；下载地址仍为即将提供。</li><li>修正私有文件排除规则，将内部工具移出公开源码索引。</li><li>公开门禁保留 Equipment、Shop 内可独立运行的测试，只明确筛出本地数据用例。</li><li>保留既有 bootstrap 默认值；本地目录数据缺失时明确失败，不再记录为测试通过。</li></ul><p>这是首个公开版本的准备记录，不代表构建包或文档站已发布。详细变更在仓库根目录的中英文更新日志中维护。</p>',9)])])}const _=e(o,[["render",c]]);export{p as __pageData,_ as default};
